import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.clip(x, -5, 5)
    return np.sin(np.sum(x)) + 0.01 * np.sum(x**2) + 0.05 * np.prod(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.clip(x, -5, 5)
    Q = np.array([[1.0, 0.1], [0.1, 1.0]])  # Positive definite matrix
    quadratic_term = x @ Q @ x
    return 0.8 * np.sin(np.sum(x)) + 0.005 * quadratic_term + 0.02 * np.prod(x) + 0.001 * np.sum(x)
